CREATE TABLE `lsboutique`.`messages` ( `id` INT NOT NULL AUTO_INCREMENT , `campaign_id` INT NOT NULL , `date` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP , `type` INT NOT NULL COMMENT '1 - sms, 2 - push, 3 - email' , `phone` VARCHAR(50) NOT NULL , `app_session_id` INT NOT NULL , `user_id` INT NOT NULL , `email` VARCHAR(50) NOT NULL , PRIMARY KEY (`id`), INDEX `campaign` (`campaign_id`)) ENGINE = InnoDB;
